TASK
Wait for a condition with polling, timeout, and cancellation.

PUBLIC CONTRACT
Module: await load('./index.js'); default export pWaitFor, named export TimeoutError.
pWaitFor(condition, options?) repeatedly calls a synchronous or asynchronous condition until it returns true. It resolves undefined, or resolves a custom value returned through pWaitFor.resolveWith(value). A false result schedules another check after interval milliseconds (default 20). before=true (default) checks immediately; before=false waits one interval first. interval is a finite non-negative number. Other condition results reject with TypeError, and exceptions/rejections from the condition propagate to the caller.
timeout is the number of milliseconds before rejecting with TimeoutError (default Infinity), or an object {milliseconds, message?, fallback?}. message customizes the error and may itself be an Error; fallback supplies the timeout result instead. A supplied AbortSignal cancels the wait with its reason. Preserve successful polling, errors, timeout, and cancellation behavior for both synchronous and asynchronous conditions.

SOURCE index.js
   1: /* eslint-disable no-await-in-loop, complexity -- Polling loop: each iteration must await the previous check before sleeping again. */
   2: const resolveValue = Symbol('resolveValue');
   3: 
   4: const sleep = (ms, signal) => new Promise((resolve, reject) => {
   5: 	if (signal?.aborted) {
   6: 		reject(signal.reason);
   7: 		return;
   8: 	}
   9: 
  10: 	const onAbort = () => {
  11: 		clearTimeout(timeout);
  12: 		reject(signal.reason);
  13: 	};
  14: 
  15: 	const timeout = setTimeout(() => {
  16: 		// `once: true` only detaches the listener when the signal aborts, so a normal resolve has to remove it.
  17: 		signal?.removeEventListener('abort', onAbort);
  18: 		resolve();
  19: 	}, ms);
  20: 
  21: 	if (signal) {
  22: 		signal.addEventListener('abort', onAbort, {once: true});
  23: 	}
  24: });
  25: 
  26: const validateOptions = (interval, timeout) => {
  27: 	if (typeof interval !== 'number' || !Number.isFinite(interval) || interval < 0) {
  28: 		throw new TypeError('Expected interval to be a finite non-negative number');
  29: 	}
  30: 
  31: 	if (typeof timeout === 'object' && timeout !== null) {
  32: 		if (typeof timeout.milliseconds !== 'number' || Number.isNaN(timeout.milliseconds) || timeout.milliseconds < 0) {
  33: 			throw new TypeError('Expected timeout.milliseconds to be a finite non-negative number');
  34: 		}
  35: 	} else if (typeof timeout === 'number' && (Number.isNaN(timeout) || timeout < 0)) {
  36: 		throw new TypeError('Expected timeout to be a finite non-negative number');
  37: 	}
  38: };
  39: 
  40: const createTimeoutError = timeout => {
  41: 	if (timeout.message instanceof Error) {
  42: 		return timeout.message;
  43: 	}
  44: 
  45: 	const message = timeout.message ?? `Promise timed out after ${timeout.milliseconds} milliseconds`;
  46: 	return new TimeoutError(message);
  47: };
  48: 
  49: const handleFallback = timeout => {
  50: 	if (timeout.fallback) {
  51: 		return timeout.fallback();
  52: 	}
  53: 
  54: 	throw createTimeoutError(timeout);
  55: };
  56: 
  57: const handleAbortError = (timeoutSignal, timeout, signal) => {
  58: 	if (timeoutSignal?.aborted) {
  59: 		// It's a timeout
  60: 		if (typeof timeout === 'object') {
  61: 			return handleFallback(timeout);
  62: 		}
  63: 
  64: 		throw new TimeoutError();
  65: 	}
  66: 
  67: 	// It's a user abort
  68: 	throw signal.reason;
  69: };
  70: 
  71: export default async function pWaitFor(condition, options = {}) {
  72: 	const {
  73: 		interval = 20,
  74: 		timeout = Infinity,
  75: 		before = true,
  76: 		signal,
  77: 	} = options;
  78: 
  79: 	validateOptions(interval, timeout);
  80: 
  81: 	// Create combined signal
  82: 	const timeoutMs = typeof timeout === 'number' ? timeout : timeout?.milliseconds ?? Infinity;
  83: 	const timeoutSignal = timeoutMs === Infinity ? undefined : AbortSignal.timeout(timeoutMs);
  84: 	const combinedSignal = timeoutSignal && signal
  85: 		? AbortSignal.any([timeoutSignal, signal])
  86: 		: (timeoutSignal ?? signal);
  87: 
  88: 	// Handle initial delay
  89: 	if (!before) {
  90: 		try {
  91: 			await sleep(interval, combinedSignal);
  92: 		} catch (error) {
  93: 			// The timeout or the user abort can expire here, before `condition` ever runs.
  94: 			if (error === combinedSignal?.reason) {
  95: 				return handleAbortError(timeoutSignal, timeout, signal);
  96: 			}
  97: 
  98: 			throw error;
  99: 		}
 100: 	}
 101: 
 102: 	// Check for pre-abort
 103: 	if (combinedSignal?.aborted) {
 104: 		return handleAbortError(timeoutSignal, timeout, signal);
 105: 	}
 106: 
 107: 	// Main loop
 108: 	while (true) {
 109: 		try {
 110: 			const value = await condition();
 111: 
 112: 			// Check for resolveWith value
 113: 			if (typeof value === 'object' && value !== null && Object.hasOwn(value, resolveValue)) {
 114: 				return value[resolveValue];
 115: 			}
 116: 
 117: 			if (value === true) {
 118: 				return;
 119: 			}
 120: 
 121: 			if (value === false) {
 122: 				await sleep(interval, combinedSignal);
 123: 				continue;
 124: 			}
 125: 
 126: 			throw new TypeError('Expected condition to return a boolean');
 127: 		} catch (error) {
 128: 			// Handle timeout vs abort vs condition error
 129: 			if (error === combinedSignal?.reason) {
 130: 				return handleAbortError(timeoutSignal, timeout, signal);
 131: 			}
 132: 
 133: 			// Some other error from condition()
 134: 			throw error;
 135: 		}
 136: 	}
 137: }
 138: 
 139: pWaitFor.resolveWith = value => ({[resolveValue]: value});
 140: 
 141: export class TimeoutError extends Error {
 142: 	constructor(message = 'Promise timed out') {
 143: 		super(message);
 144: 		this.name = 'TimeoutError';
 145: 	}
 146: }

